    BRONZE(BigDecimal.ZERO),
    PRATA(new BigDecimal("0.02")),
    OURO(new BigDecimal("0.05")) {
        @Override
        BigDecimal aplicarFrete(BigDecimal frete) {
            return ZERO;
        }

        @Override
        boolean temBrinde(BigDecimal subtotal) {
            return subtotal.compareTo(new BigDecimal("500")) > 0;
