        String[][] campos = {
                {"modalidadeEntrega", "\"RETIRADA_LOJA\""},
                {"formaPagamento", "\"PIX\""},
                {"nivelClube", "\"BRONZE\""},
                {"regiao", "\"SUL\""},
        };
        StringBuilder json = new StringBuilder("{\"itens\": [{\"nome\": \"Meia\", \"precoUnitario\": 19.90, "
                + "\"quantidade\": 1, \"pesoKg\": 0.10}]");
        for (String[] c : campos) {
            String v = c[0].equals(campo) ? "\"" + valor + "\"" : c[1];
            json.append(", \"").append(c[0]).append("\": ").append(v);
        }
        if (campo.equals("cupom")) {
            json.append(", \"cupom\": \"").append(valor).append("\"");
        }
        return json.append("}").toString();
