3	import java.math.BigDecimal;
4	import java.math.MathContext;
5	import java.math.RoundingMode;
6	
7	import static com.loja.resumo.calculo.Dinheiro.arredonda;
8	
9	public enum FormaPagamento {
10	
11	    PIX {
12	        @Override
13	        Pagamento calcular(BigDecimal total, int parcelas) {
14	            return aVista(total.subtract(arredonda(total.multiply(new BigDecimal("0.05")))));
15	        }
16	    },
17	    BOLETO {
18	        @Override
19	        boolean disponivel(BigDecimal total) {
20	            return total.compareTo(new BigDecimal("1000")) <= 0;
21	        }
22	
23	        @Override
24	        Pagamento calcular(BigDecimal total, int parcelas) {
25	            return aVista(total.add(new BigDecimal("3.49")));
26	        }
27	    },
28	    CARTAO {
29	        @Override
30	        boolean parcelamentoPermitido(int parcelas) {
31	            return parcelas >= 1 && parcelas <= 12;
32	        }
33	
34	        @Override
35	        Pagamento calcular(BigDecimal total, int parcelas) {
36	            if (parcelas <= 3) {
37	                return new Pagamento(total, parcelas, arredonda(total.divide(BigDecimal.valueOf(parcelas), MATH)));
38	            }
39	            BigDecimal fatorInverso = BigDecimal.ONE.divide(BigDecimal.ONE.add(TAXA_JUROS).pow(parcelas, MATH), MATH);
40	            BigDecimal parcela = arredonda(total.multiply(TAXA_JUROS)
41	                    .divide(BigDecimal.ONE.subtract(fatorInverso), MATH));
42	            return new Pagamento(parcela.multiply(BigDecimal.valueOf(parcelas)), parcelas, parcela);
43	        }
44	    };
45	
46	    private static final BigDecimal TAXA_JUROS = new BigDecimal("0.0199");
47	    private static final MathContext MATH = new MathContext(30, RoundingMode.HALF_EVEN);
48	
49	    boolean parcelamentoPermitido(int parcelas) {
50	        return parcelas == 1;
51	    }
52	
53	    boolean disponivel(BigDecimal total) {
54	        return true;
55	    }
56	
57	    abstract Pagamento calcular(BigDecimal total, int parcelas);
58	
59	    static Pagamento aVista(BigDecimal totalFinal) {
60	        return new Pagamento(totalFinal, 1, totalFinal);
61	    }
62	}
