    private static <E extends Enum<E>> E buscar(Class<E> tipo, String codigo, String erro) {
        return Arrays.stream(tipo.getEnumConstants())
                .filter(e -> e.name().equals(codigo))
                .findFirst()
                .orElseThrow(() -> new ResumoException(erro));
    }
